'use strict';

// MODULES //

var tape = require( 'tape' );
var abs = require( '@stdlib/math/base/special/abs' );
var EPS = require( '@stdlib/constants/float64/eps' );
var incrNanMme = require( './../lib' );


// TESTS //

tape( 'main export is a function', function testMainExport( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof incrNanMme, 'function', 'main export is a function' );
	t.end();
});

tape( 'throws if not given a positive integer', function testInvalidInput( t ) {
	var values = [ '5', -5, 0, 3.14, true, null, undefined, NaN, [], {}, function noop() {} ];
	var i;

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws error for ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValueTest() {
			incrNanMme( value );
		};
	}
});

tape( 'returns an accumulator function', function testReturnsFunction( t ) {
	var acc = incrNanMme( 3 );
	t.strictEqual( typeof acc, 'function', 'returns a function' );
	t.end();
});

tape( 'accumulator computes moving mean error incrementally', function testIncrementalBehavior( t ) {
	var expected = [ 1, -1.5, 0, -3, -8/3, -2/3 ];
	var actual;
	var delta;
	var data = [
		[ 2, 3 ],
		[ 3, -1 ],
		[ 2, 5 ],
		[ 4, -4 ],
		[ 3, 0 ],
		[ -4, 5 ]
	];
	var acc = incrNanMme( 3 );
	var tol;
	var i;

	for ( i = 0; i < data.length; i++ ) {
		actual = acc( data[ i ][ 0 ], data[ i ][ 1 ] );
		if ( actual === expected[ i ] ) {
			t.strictEqual( actual, expected[ i ] );
		} else {
			delta = abs( expected[ i ] - actual );
			tol = EPS * abs( expected[ i ] );
			t.strictEqual( delta <= tol, true, 'within tolerance' );
		}
	}
	t.end();
});

tape( 'returns current mean error when no input', function testNoInput( t ) {
	var acc = incrNanMme( 2 );

	acc( 2, 3 );
	acc( 3, -5 );
	acc( 1, 10 );

	t.strictEqual( acc(), 0.5 );
	t.end();
});

tape( 'returns null if no data', function testNoData( t ) {
	var acc = incrNanMme( 3 );
	t.strictEqual( acc(), null );
	t.end();
});

tape( 'ignores NaN inputs', function testNanHandling( t ) {
	var expected = [ null, null, null, 0, 0 ];
	var data = [
		[ NaN, 1 ],
		[ 1, NaN ],
		[ NaN, NaN ],
		[ 2, 2 ],
		[ NaN, 3 ]
	];
	var acc = incrNanMme( 3 );
	var i;
	var v;

	for ( i = 0; i < data.length; i++ ) {
		v = acc( data[ i ][ 0 ], data[ i ][ 1 ] );
		t.strictEqual( v, expected[ i ], 'window ' + i );
	}
	t.end();
});
